   "slug": "why-ben-shapiros-media-empire-is-collapsing",
   "title": "Why Ben Shapiro’s Media Empire Is Collapsing",
   "liveUrl": "https://nymag.com/intelligencer/article/why-ben-shapiros-media-empire-is-collapsing.html",
   "archiveUrl": "https://web.archive.org/web/20260514112033/https://nymag.com/intelligencer/article/why-ben-shapiros-media-empire-is-collapsing.html",
