   "slug": "something-doesnt-add-up-about-the-shohei-ohtani-gambling-story",
   "title": "Something Doesn’t Add Up About the Shohei Ohtani Gambling Story",
   "liveUrl": "https://nymag.com/intelligencer/article/the-shohei-ohtani-translator-gambling-story-doesnt-add-up.html",
   "archiveUrl": "https://web.archive.org/web/20240321194916/https://nymag.com/intelligencer/article/the-shohei-ohtani-translator-gambling-story-doesnt-add-up.html",
   "archiveTimestamp": "20240321194916",
   "status": "ok",
