   "id": "052",
   "slug": "the-yimby-war-breaking-out-on-the-left",
   "title": "The YIMBY War Breaking Out on the Left",
   "liveUrl": "https://nymag.com/intelligencer/2022/09/a-war-is-breaking-out-on-the-left-between-yimbys-and-nimbys.html",
   "archiveUrl": "https://web.archive.org/web/20220916193308/https://nymag.com/intelligencer/2022/09/a-war-is-breaking-out-on-the-left-between-yimbys-and-nimbys.html",
   "archiveTimestamp": "20220916193308",
   "status": "ok",
