   "liveUrl": "https://nymag.com/intelligencer/2022/07/janet-difiores-resignation-gives-ny-dems-an-opening.html",
   "archiveUrl": "https://web.archive.org/web/20220711210906/https://nymag.com/intelligencer/2022/07/janet-difiores-resignation-gives-ny-dems-an-opening.html",
